import {
  expect,
  expectStatus,
  test,
  uniqueName,
  type APIRequestContext,
  type Document,
  type Extraction,
  type Vendor,
} from "../../fixtures";

const POLL_ATTEMPTS = 60;
const POLL_INTERVAL_MS = 500;

async function uploadDocument(member: APIRequestContext, vendorId: string, kind: string): Promise<Document> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 test document") },
    },
  });
  return expectStatus<Document>(response, 201);
}

async function waitForExtraction(reviewer: APIRequestContext, documentId: string): Promise<Extraction> {
  for (let attempt = 0; attempt < POLL_ATTEMPTS; attempt++) {
    const document = await expectStatus<Document>(await reviewer.get(`/api/documents/${documentId}`), 200);
    if (document.status === "extracted") {
      return expectStatus<Extraction>(await reviewer.get(`/api/documents/${documentId}/extraction`), 200);
    }
    if (document.status === "failed") {
      throw new Error(`extraction failed for document ${documentId}`);
    }
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }
  throw new Error(`document ${documentId} was not extracted in time`);
}

test.describe("vendor lifecycle", () => {
  test(
    "resubmitting without replacing the rejected w9 is refused with documents_incomplete",
    { tag: "@LIF-04" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads all three required documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const uniq = uniqueName("lif04-vendor");

      const vendor = await expectStatus<Vendor>(
        await member.post("/api/vendors", {
          data: { name: uniq, category: "services", contact_email: `${uniq}@example.test` },
        }),
        201,
      );

      const w9 = await uploadDocument(member, vendor.id, "w9");
      const insurance = await uploadDocument(member, vendor.id, "insurance_certificate");
      const contract = await uploadDocument(member, vendor.id, "contract");

      // Arrange: extraction runs for each document; the first submission goes through.
      await waitForExtraction(reviewer, w9.id);
      const insuranceExtraction = await waitForExtraction(reviewer, insurance.id);
      const contractExtraction = await waitForExtraction(reviewer, contract.id);

      await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

      // Arrange: a reviewer rejects the w9 and approves the other two.
      const w9Extraction = await waitForExtraction(reviewer, w9.id);
      await expectStatus<Extraction>(
        await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
          data: { decision: "reject", note: "W-9 is illegible" },
        }),
        200,
      );
      await expectStatus<Extraction>(
        await reviewer.post(`/api/extractions/${insuranceExtraction.id}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );
      await expectStatus<Extraction>(
        await reviewer.post(`/api/extractions/${contractExtraction.id}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );

      // Act: the member submits again without replacing the rejected w9.
      const response = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert: refused, naming only the w9 as missing.
      const body = await expectStatus<{ error: { code: string } & Record<string, unknown> }>(response, 409);
      expect(body.error.code).toBe("documents_incomplete");

      const serialized = JSON.stringify(body.error);
      expect(serialized).toContain("w9");
      expect(serialized).not.toContain("insurance_certificate");
      expect(serialized).not.toContain("contract");
    },
  );
});
